(() => {
  'use strict';
  const ROOT_ORDER=['A','Bb','B','C','C#','D','Eb','E','F','F#','G','Ab'];
  const TYPES=['major','minor','7','maj7','m7','add9','sus4','9','13','7b9','6','madd9','m7b5','dim7','aug','7#5','7#9'];
  const LABEL={major:'Major',minor:'Minor','7':'7',maj7:'Maj7',m7:'m7',add9:'Add9',sus4:'Sus4','9':'9','13':'13','7b9':'7♭9','6':'6',madd9:'m(add9)',m7b5:'m7♭5',dim7:'dim7',aug:'Aug','7#5':'7♯5','7#9':'7♯9'};
  const ROOT_PC={C:0,'C#':1,Db:1,D:2,Eb:3,E:4,F:5,'F#':6,Gb:6,G:7,Ab:8,A:9,Bb:10,B:11};
  const TUNING=[4,9,2,7,11,4],KEY='chord-pocket-selected-v1',$=id=>document.getElementById(id);
  const state={chords:[],byId:new Map(),selected:[],view:'browse',filters:{search:'',types:[...TYPES],allShapes:false},practice:{order:[],index:0,revealed:false,timer:null,interval:null,finished:false,nailed:0,missed:0,total:0,signature:''}};
  const dom={main:$('app-main'),status:$('catalog-status'),offline:$('offline-status'),count:$('result-count'),search:$('search-input'),clear:$('clear-search'),families:$('family-filter'),familyLabel:$('family-filter-label'),allFamilies:$('all-families'),allShapes:$('show-all-shapes'),typeFilter:$('type-filter'),grid:$('chord-grid'),empty:$('browse-empty'),error:$('browse-error'),retry:$('retry-load'),savedGrid:$('saved-grid'),savedEmpty:$('saved-empty'),savedCount:$('saved-count'),badge:$('nav-saved-count'),practiceEmpty:$('practice-empty'),practiceStage:$('practice-stage'),practiceProgress:$('practice-progress'),practiceName:$('practice-name'),practiceShape:$('practice-shape'),practiceReveal:$('practice-reveal'),practiceDiagram:$('practice-diagram'),practiceCover:$('practice-cover'),practiceComplete:$('practice-complete'),practiceKicker:$('practice-kicker'),practiceNameWrap:$('practice-name-wrap'),show:$('show-practice'),countdown:$('reveal-countdown'),nailed:$('nailed-practice'),missed:$('missed-practice'),verdict:$('practice-verdict'),summary:$('practice-summary'),restart:$('restart-practice'),end:$('end-practice'),dialog:$('detail-dialog'),detailName:$('detail-name'),detailMeta:$('detail-meta'),detailDiagram:$('detail-diagram'),close:$('close-dialog'),toast:$('toast')};
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize=value=>String(value??'').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/♭/g,'b').replace(/♯/g,'#').replace(/\s+/g,'');
  const name=chord=>String(chord.name||'').trim(),roots=chord=>[...new Set([chord.root,...(chord.aliases||[])])],shape=chord=>`Shape ${chord.voicing||1}`;
  function variants(chord){const base=chord.root.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return [...new Set(roots(chord).flatMap(root=>[name(chord).replace(new RegExp(`^${base}`,'i'),root),`${root}${chord.type}`,`${root}${LABEL[chord.type]||chord.type}`]))];}
  function isRoot(chord,string,fret){if(fret==='x')return false;const value=fret==='0'?0:Number(fret);return Number.isFinite(value)&&(TUNING[string]+value)%12===ROOT_PC[chord.root];}
  function diagram(chord){
    const xs=[42,72,102,132,162,192],top=62,step=34,start=Math.max(1,Number(chord.startFret||1)),fingers=Array.isArray(chord.fingers)?chord.fingers:[];
    const rootString=chord.frets.findIndex((fret,string)=>isRoot(chord,string,fret));
    const grid=xs.map(x=>`<line x1="${x}" y1="${top}" x2="${x}" y2="${top+step*5}"/>`).join('')+Array.from({length:6},(_,i)=>`<line x1="${xs[0]}" y1="${top+i*step}" x2="${xs[5]}" y2="${top+i*step}"/>`).join('');
    const barres=(chord.barres||[]).map(b=>`<line class="diagram-barre" x1="${xs[Math.max(0,b.fromString-1)]}" y1="${top+(b.fret-start+.5)*step}" x2="${xs[Math.min(5,b.toString-1)]}" y2="${top+(b.fret-start+.5)*step}"/>`).join('');
    const markers=chord.frets.map((fret,string)=>{const x=xs[string],root=string===rootString;if(fret==='x')return `<text class="diagram-muted" x="${x}" y="43">×</text>`;if(fret==='0')return `${root?`<rect class="diagram-root" x="${x-11}" y="25" width="22" height="22" rx="2"/>`:''}<circle class="diagram-open" cx="${x}" cy="36" r="7"/>`;const y=top+(Number(fret)-start+.5)*step;return `${root?`<rect class="diagram-root" x="${x-12}" y="${y-12}" width="24" height="24" rx="2"/>`:''}<circle class="diagram-dot" cx="${x}" cy="${y}" r="9"/>${fingers[string]?`<text class="diagram-finger" x="${x}" y="${y+4}">${fingers[string]}</text>`:''}`;}).join('');
    const alt=`${name(chord)}, ${shape(chord)} guitar chord diagram`;
    return `<svg class="chord-diagram" viewBox="0 0 240 250" role="img" aria-label="${escape(alt)}"><title>${escape(alt)}</title><g class="diagram-grid">${grid}${start===1?`<line class="diagram-nut" x1="${xs[0]}" y1="${top}" x2="${xs[5]}" y2="${top}"/>`:''}</g>${start>1?`<text class="diagram-position" x="207" y="${top+22}">${start}fr</text>`:''}<g>${barres}${markers}</g></svg>`;
  }
  function validate(raw){if(!Array.isArray(raw))throw Error('Invalid library');const seen=new Set();return raw.filter(c=>c&&typeof c.id==='string'&&!seen.has(c.id)&&c.root&&c.type&&Array.isArray(c.frets)&&c.frets.length===6&&(seen.add(c.id),true)).sort((a,b)=>ROOT_ORDER.indexOf(a.root)-ROOT_ORDER.indexOf(b.root)||TYPES.indexOf(a.type)-TYPES.indexOf(b.type)||(a.voicing||1)-(b.voicing||1));}
  function matches(chord,query){const q=normalize(query);if(!q)return true;return [...roots(chord),...variants(chord),chord.type,LABEL[chord.type]].some(v=>normalize(v).includes(q));}
  function visible(){return state.chords.filter(c=>state.filters.types.includes(c.type)&&(state.filters.allShapes||Number(c.voicing||1)===1)&&matches(c,state.filters.search));}
  function selectedChords(){return state.selected.map(id=>state.byId.get(id)).filter(Boolean);}
  function card(chord){const selected=state.selected.includes(chord.id);return `<article class="chord-card" data-id="${escape(chord.id)}"><button class="card-image-button" data-action="detail" type="button" aria-label="Open ${escape(name(chord))} details">${diagram(chord)}</button><div class="card-content"><div><h2 class="card-name">${escape(name(chord))}</h2><p class="card-shape">${shape(chord)}</p></div><button class="add-control${selected?' is-selected':''}" data-action="toggle" type="button" aria-label="${selected?'Remove':'Add'} ${escape(name(chord))}" aria-pressed="${selected}">${selected?'✓':'+'}</button></div></article>`;}
  function renderBrowse(){if(!state.chords.length)return;const rows=visible();dom.count.textContent=`${rows.length} shown · ${state.chords.length} total`;dom.grid.innerHTML=rows.map(card).join('');dom.empty.hidden=rows.length!==0;dom.grid.hidden=rows.length===0;dom.clear.hidden=!state.filters.search;}
  function renderSaved(){const rows=selectedChords();dom.savedCount.textContent=`${rows.length} saved`;dom.badge.textContent=rows.length>99?'99+':rows.length;dom.badge.hidden=!rows.length;dom.savedGrid.innerHTML=rows.map(card).join('');dom.savedEmpty.hidden=rows.length!==0;dom.savedGrid.hidden=rows.length===0;}
  function save(){try{localStorage.setItem(KEY,JSON.stringify(state.selected));}catch(_){toast('Selection could not be saved');}}
  function toggle(id){state.selected=state.selected.includes(id)?state.selected.filter(x=>x!==id):[...state.selected,id];save();renderBrowse();renderSaved();if(state.view==='practice')startPractice();toast(state.selected.includes(id)?'Added to My Chords':'Removed from My Chords');}
  function toast(message){dom.toast.textContent=message;dom.toast.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>dom.toast.hidden=true,2200);}
  function details(id){const chord=state.byId.get(id);if(!chord)return;dom.detailName.textContent=name(chord);dom.detailMeta.textContent=`${shape(chord)} · ${LABEL[chord.type]||chord.type}`;dom.detailDiagram.innerHTML=diagram(chord);dom.dialog.showModal?dom.dialog.showModal():dom.dialog.setAttribute('open','');}
  function close(){dom.dialog.close?dom.dialog.close():dom.dialog.removeAttribute('open');}
  function shuffle(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
  function clearTimer(){clearTimeout(state.practice.timer);clearInterval(state.practice.interval);state.practice.timer=null;state.practice.interval=null;}
  function startPractice(){clearTimer();const rows=selectedChords();state.practice={order:shuffle(rows),index:0,revealed:false,finished:false,nailed:0,missed:0,total:rows.length,signature:state.selected.join('|')};renderPractice();}
  function reveal(){clearTimer();state.practice.revealed=true;dom.practiceCover.hidden=true;dom.practiceReveal.hidden=false;dom.nailed.disabled=false;dom.missed.disabled=false;dom.countdown.textContent='Give your verdict';}
  function timer(){clearTimer();const started=Date.now();dom.countdown.textContent='Reveals in 3s';state.practice.interval=setInterval(()=>{const left=Math.max(0,3000-(Date.now()-started));dom.countdown.textContent=left?`Reveals in ${Math.ceil(left/1000)}s`:'';},100);state.practice.timer=setTimeout(reveal,3000);}
  function renderPractice(){const rows=selectedChords();if(!rows.length){clearTimer();dom.practiceEmpty.hidden=false;dom.practiceStage.hidden=true;return;}dom.practiceEmpty.hidden=true;dom.practiceStage.hidden=false;if(!state.practice.order.length||state.practice.signature!==state.selected.join('|'))return startPractice();const p=state.practice;if(p.finished){dom.practiceProgress.textContent='Round complete';dom.practiceKicker.hidden=true;dom.practiceNameWrap.hidden=true;dom.practiceReveal.hidden=true;dom.practiceCover.hidden=true;dom.practiceComplete.hidden=false;dom.verdict.hidden=true;dom.summary.textContent=p.missed?`${p.total} chords nailed · ${p.missed} needed another pass`:`${p.total} chords nailed, clean first pass`;return;}dom.practiceKicker.hidden=false;dom.practiceNameWrap.hidden=false;dom.practiceComplete.hidden=true;dom.verdict.hidden=false;const chord=p.order[p.index];dom.practiceProgress.textContent=`Nailed ${p.nailed} of ${p.total}${p.missed?` · ${p.missed} missed`:''}`;dom.practiceName.textContent=name(chord);dom.practiceShape.textContent=shape(chord);dom.practiceDiagram.innerHTML=diagram(chord);dom.practiceReveal.hidden=!p.revealed;dom.practiceCover.hidden=p.revealed;dom.nailed.disabled=!p.revealed;dom.missed.disabled=!p.revealed;if(!p.revealed)timer();}
  function verdict(pass){const p=state.practice;if(!p.revealed)return;clearTimer();if(pass){p.nailed++;p.index++;}else{p.missed++;p.order.push(p.order[p.index]);p.index++;}if(p.index>=p.order.length)p.finished=true;else p.revealed=false;renderPractice();}
  function navigate(view){state.view=['browse','saved','practice'].includes(view)?view:'browse';document.querySelectorAll('.view').forEach(v=>v.hidden=v.dataset.view!==state.view);document.querySelectorAll('.nav-item').forEach(v=>v.classList.toggle('is-active',v.dataset.tab===state.view));if(state.view==='browse')renderBrowse();if(state.view==='saved')renderSaved();if(state.view==='practice')renderPractice();else clearTimer();if(location.hash!==`#${state.view}`)history.replaceState(null,'',`#${state.view}`);}
  function updateFilters(){const count=state.filters.types.length;dom.allFamilies.checked=count===TYPES.length;dom.allFamilies.indeterminate=count>0&&count<TYPES.length;dom.familyLabel.textContent=count===TYPES.length?'All families':count===1?LABEL[state.filters.types[0]]:`${count} families`;dom.allShapes.checked=state.filters.allShapes;dom.typeFilter.querySelectorAll('input').forEach(i=>i.checked=state.filters.types.includes(i.value));}
  function populateFilters(){TYPES.forEach(type=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=type;label.append(input,document.createTextNode(LABEL[type]));dom.typeFilter.append(label);});updateFilters();}
  async function load(){dom.error.hidden=true;try{const response=await fetch('chords.json',{cache:'no-store'});if(!response.ok)throw Error();state.chords=validate(await response.json());state.byId=new Map(state.chords.map(c=>[c.id,c]));state.selected=state.selected.filter(id=>state.byId.has(id));dom.status.textContent=`${state.chords.length} shapes`;renderSaved();navigate(state.view);offline();}catch(_){dom.status.textContent='Library unavailable';dom.error.hidden=false;dom.grid.hidden=true;}}
  async function offline(){if(!navigator.serviceWorker)return;try{const registration=await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;(navigator.serviceWorker.controller||registration.active)?.postMessage({type:'PREPARE_OFFLINE',urls:['chords.json']});dom.offline.hidden=false;dom.offline.textContent='Preparing offline…';}catch(_){dom.offline.hidden=false;dom.offline.textContent='Offline unavailable';}}
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(saved))state.selected=[...new Set(saved.filter(x=>typeof x==='string'))];}catch(_){}
  populateFilters();state.view=['browse','saved','practice'].includes(location.hash.slice(1))?location.hash.slice(1):(state.selected.length?'saved':'browse');navigate(state.view);load();
  dom.search.addEventListener('input',e=>{state.filters.search=e.target.value;renderBrowse();});dom.clear.addEventListener('click',()=>{state.filters.search='';dom.search.value='';renderBrowse();dom.search.focus();});
  dom.typeFilter.addEventListener('change',e=>{if(!TYPES.includes(e.target.value))return;state.filters.types=TYPES.filter(t=>t===e.target.value?e.target.checked:state.filters.types.includes(t));updateFilters();renderBrowse();});
  dom.allFamilies.addEventListener('change',()=>{state.filters.types=dom.allFamilies.checked?[...TYPES]:[];updateFilters();renderBrowse();});dom.allShapes.addEventListener('change',()=>{state.filters.allShapes=dom.allShapes.checked;renderBrowse();});
  document.addEventListener('click',e=>{const nav=e.target.closest('[data-tab]');if(nav){e.preventDefault();navigate(nav.dataset.tab);return;}const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go);return;}const action=e.target.closest('[data-action]'),item=e.target.closest('[data-id]');if(action&&item){if(action.dataset.action==='toggle')toggle(item.dataset.id);else details(item.dataset.id);}if(dom.families.open&&!dom.families.contains(e.target))dom.families.open=false;});
  dom.show.addEventListener('click',reveal);dom.nailed.addEventListener('click',()=>verdict(true));dom.missed.addEventListener('click',()=>verdict(false));dom.restart.addEventListener('click',startPractice);dom.end.addEventListener('click',()=>navigate('browse'));dom.retry.addEventListener('click',load);dom.close.addEventListener('click',close);dom.dialog.addEventListener('click',e=>{if(e.target===dom.dialog)close();});window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
  navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_PROGRESS')dom.offline.textContent='Preparing offline…';if(e.data?.type==='OFFLINE_READY')dom.offline.textContent=e.data.complete?'Offline ready':'Offline partial';});
  const topbar=document.querySelector('.topbar');const sync=()=>document.documentElement.style.setProperty('--topbar-height',`${Math.ceil(topbar.getBoundingClientRect().height)}px`);if(typeof ResizeObserver!=='undefined')new ResizeObserver(sync).observe(topbar);sync();
  window.ChordPocketLogic=Object.freeze({normalize,validate,matches,diagram});
})();
